  "weighted-average": { name: "加重平均計算", shortName: "加重平均", title: "加重平均計算｜値と重みから平均を算出", description: "それぞれの値に重みを設定し、重要度や構成比を反映した加重平均を求めます。", keywords: ["加重平均 計算", "加重平均", "重み付き平均"], formula: "加重平均 = Σ(値 × 重み) ÷ Σ(重み)。", example: { question: "値80に重み2、値90に重み3を付けた平均は？", answer: "(80 × 2 + 90 × 3) ÷ 5 = 86です。" }, faq: { question: "重みの合計を100にする必要がありますか？", answer: "いいえ。重みは0以上で、合計が0より大きければ計算できます。" }, results: ["加重平均"] },
  cagr: { name: "CAGR計算", shortName: "CAGR", title: "CAGR計算｜年平均成長率をかんたん算出", description: "初期値、最終値、期間から複利ベースの年平均成長率を計算します。", keywords: ["CAGR 計算", "年平均成長率", "複合年間成長率"], formula: "CAGR = (最終値 ÷ 初期値)^(1 ÷ 年数) − 1。", example: { question: "100から121へ2年間で増えた場合のCAGRは？", answer: "年平均成長率は年10%です。" }, faq: { question: "CAGRは毎年の平均リターンと同じですか？", answer: "開始値と終了値をつなぐ一定の年率です。途中の値動きを表すものではありません。" }, results: ["年平均成長率 (CAGR)"] },
  "unit-price": { name: "単価計算", shortName: "単価", title: "単価計算｜1個あたりの価格と合計金額", description: "合計金額と数量から単価を計算するか、単価と数量から合計金額を求めます。", keywords: ["単価 計算", "1個あたりの値段", "単位価格 比較"], formula: "単価 = 合計金額 ÷ 数量。合計金額 = 単価 × 数量。", example: { question: "12個で18,000 KRWの商品は1個いくらですか？", answer: "1個あたり1,500 KRWです。" }, faq: { question: "容量の違う商品も比べられますか？", answer: "はい。同じ単位（1個あたり、1kgあたりなど）の価格にそろえて比較できます。" }, results: ["単価"], variants: { total: ["合計金額"] } },
  "unit-converter": { name: "単位変換", shortName: "単位変換", title: "単位変換｜長さ・重さ・容量・温度", description: "長さ、重さ、容量のメートル法・ヤードポンド法の単位と、摂氏・華氏を変換します。", keywords: ["単位 変換", "長さ 単位 換算", "重さ 換算", "摂氏 華氏 変換"], formula: "線形変換 = 値 × 変換元係数 ÷ 変換先係数。華氏 = 摂氏 × 9 ÷ 5 + 32。", example: { question: "1インチは何センチですか？", answer: "1インチは2.54センチです。" }, faq: { question: "温度も単純な倍率で変換しますか？", answer: "いいえ。摂氏と華氏は基準点が異なるため、倍率に加えてオフセットを使います。" }, results: ["変換結果"] },
  "simple-interest": { name: "単利計算", shortName: "単利", title: "単利計算｜元金と期間から利息・元利合計", description: "利息を当初の元金だけに付ける単利方式で、税引前の利息と元利合計を試算します。", keywords: ["単利 計算", "単利 計算式", "元金 利息 計算"], formula: "利息 = 元金 × 年利 × 年数。元利合計 = 元金 + 利息。", example: { question: "元金1,000,000 KRWを年5%で2年間預けると？", answer: "税引前利息は100,000 KRW、元利合計は1,100,000 KRWです。" }, faq: { question: "単利と複利の違いは何ですか？", answer: "単利は当初の元金だけに利息が付きます。複利はそれまでに付いた利息も次の計算に含めます。" }, results: ["単利利息", "元利合計"] },
  "savings-interest": { name: "積立預金利息計算", shortName: "積立利息", title: "積立預金利息計算｜毎月積立と満期額", description: "毎月同額を積み立てる場合の預入元金、税引前の利息、満期額を試算します。", keywords: ["積立 利息 計算", "毎月 積立 計算", "積立 満期額"], formula: "預入元金 = 毎月の積立額 × 月数。利息は各積立分の残り期間に年利を適用して合計します。", example: { question: "毎月100,000 KRWを年12%で12か月積み立てると？", answer: "元金は1,200,000 KRW。月末積立・単利の税引前利息は約66,000 KRWです。" }, faq: { question: "毎月の積立日はいつとして計算しますか？", answer: "各月の月末に積み立てる前提です。最後の積立分には利息が付きません。" }, results: ["積立元金", "税引前の利息見込額", "税引前の満期見込額"] },
  "deposit-interest": { name: "定期預金利息計算", shortName: "預金利息", title: "定期預金利息計算｜税引前利息と満期額", description: "一括で預ける元金、年利、月数から単利ベースの税引前利息と満期額を試算します。", keywords: ["預金 利息 計算", "定期預金 満期", "税引前 利息"], formula: "税引前利息 = 預入額 × 年利 × 月数 ÷ 12。満期額 = 預入額 + 利息。", example: { question: "10,000,000 KRWを年3.6%で12か月預けると？", answer: "税引前利息は360,000 KRW、満期額は10,360,000 KRWです。" }, faq: { question: "積立預金の計算とはどう違いますか？", answer: "こちらは最初に一括で預ける計算です。積立計算では毎月の預入分ごとに利息期間が異なります。" }, results: ["税引前利息", "税引前の満期見込額"] },
